export function createDetectionEngine(
  config: SecurityGuardConfig,
  warnings?: string[],
): DetectionEngine {
  const patterns = getPatterns(
    config.categories,
    config.disabledPatterns,
    config.customPatterns,
    warnings,
  )
  return new DetectionEngine(patterns)
}

